import { Injectable } from '@nestjs/common';
import { createMongoAbility, type MongoAbility } from '@casl/ability';
import type { UserRole } from '../generated/prisma/client';
import { PrismaService } from '../database/prisma.service';

export type AbilityAction = 'manage' | 'create' | 'read' | 'update' | 'delete' | 'complete';
export type AbilitySubject = 'Task' | 'User' | 'Role' | 'all';
export type AppAbility = MongoAbility<[AbilityAction, AbilitySubject]>;
export type AppRule = {
  action: AbilityAction | AbilityAction[];
  subject: AbilitySubject | AbilitySubject[];
  conditions?: Record<string, unknown>;
  inverted?: boolean;
};

export interface AbilityUser {
  id: string;
  role: UserRole;
  customRoleId?: string | null;
}

@Injectable()
export class AbilityFactory {
  constructor(private readonly prisma: PrismaService) {}

  async rulesForUser(user: AbilityUser): Promise<AppRule[]> {
    if (user.role === 'ADMIN') {
      return [
        { action: 'manage', subject: 'all' },
        { action: 'complete', subject: 'Task' },
      ];
    }
    if (user.customRoleId) {
      const permissions = await this.prisma.rolePermission.findMany({
        where: { roleId: user.customRoleId },
        select: { action: true, subject: true, conditions: true },
      });
      return permissions.map((permission) => ({
        action: permission.action as AbilityAction,
        subject: permission.subject as AbilitySubject,
        ...(permission.conditions ? { conditions: JSON.parse(permission.conditions) as Record<string, unknown> } : {}),
      })) as AppRule[];
    }

    switch (user.role) {
      case 'MANAGER':
        return [
          { action: 'manage', subject: 'Task' },
          { action: 'complete', subject: 'Task' },
          { action: 'read', subject: 'User' },
        ];
      case 'USER':
      default:
        return [
          { action: 'read', subject: 'Task', conditions: { userId: user.id } },
          { action: 'complete', subject: 'Task', conditions: { userId: user.id } },
        ];
    }
  }

  async createForUser(user: AbilityUser): Promise<AppAbility> {
    return createMongoAbility<[AbilityAction, AbilitySubject]>(await this.rulesForUser(user) as never[]);
  }
}
